/**
 * Verb data ships with the app as static JSON (public/data, generated by
 * tools/conjugator — `npm run conjugations`). Rank-band shards load lazily, so a top-10
 * round fetches ~13 KB; the service worker / HTTP cache covers offline.
 */
export interface Meta {
  pronouns: string[];
  tenses: string[];
  moods: string[];
  bands: { lo: number; hi: number; file: string }[];
}
interface VerbEntry { v: string; rank: number; count: number }
/** verb → "tense.mood" → forms in `meta.pronouns` order (null where none exists). */
type Shard = Record<string, Record<string, (string | null)[]>>;

const cache = new Map<string, Promise<unknown>>();
function load<T>(path: string): Promise<T> {
  let p = cache.get(path) as Promise<T> | undefined;
  if (!p) {
    p = fetch(path).then((r) => {
      if (!r.ok) throw new Error(`Failed to load ${path}: ${r.status}`);
      return r.json() as Promise<T>;
    });
    p.catch(() => cache.delete(path)); // let a failed load retry
    cache.set(path, p);
  }
  return p;
}

export const getMeta = () => load<Meta>('/data/meta.json');
const getVerbs = () => load<VerbEntry[]>('/data/verbs.json');

/** "top20" → 20. */
export function parseVerbClass(verbClass: string): number {
  const m = /^top(\d+)$/.exec(verbClass.toLowerCase());
  if (!m) throw new Error(`Unsupported verb class: '${verbClass}'. Use 'top<number>' (e.g. top10).`);
  return Number(m[1]);
}

/** Infinitives of the N most frequent verbs, in rank order. */
export async function getTopVerbs(verbClass: string): Promise<string[]> {
  const n = parseVerbClass(verbClass);
  return (await getVerbs()).slice(0, n).map((x) => x.v);
}

/** Shards covering ranks 1..n. */
async function shardsFor(n: number): Promise<Shard[]> {
  const meta = await getMeta();
  return Promise.all(meta.bands.filter((b) => b.lo <= n).map((b) => load<Shard>(`/data/conjugations/${b.file}`)));
}

export interface Question { verb: string; pronoun: string; tense: string; mood: string; answer: string }

/** Random unique (verb, pronoun, tense, mood) questions — port of the old QuestionService. */
export async function generateQuestions(
  pronouns: string[], tenses: string[], moods: string[], limit: number, verbClass: string,
): Promise<Question[]> {
  const [meta, verbs, shards] = await Promise.all([getMeta(), getTopVerbs(verbClass), shardsFor(parseVerbClass(verbClass))]);
  const table: Shard = Object.assign({}, ...shards);
  const pick = <T,>(xs: T[]) => xs[Math.floor(Math.random() * xs.length)];
  const out: Question[] = [];
  const seen = new Set<string>();
  for (let attempts = 0; out.length < limit && attempts < limit * 20; attempts++) {
    const verb = pick(verbs), pronoun = pick(pronouns), tense = pick(tenses), mood = pick(moods);
    const key = `${verb}|${pronoun}|${tense}|${mood}`;
    if (seen.has(key)) continue;
    const answer = table[verb]?.[`${tense}.${mood}`]?.[meta.pronouns.indexOf(pronoun)];
    if (!answer) continue; // no such form (e.g. imperative + present_perfect)
    seen.add(key);
    out.push({ verb, pronoun, tense, mood, answer });
  }
  return out;
}

/** Indicative forms for the conjugation popup, keyed `${tense}_${pronoun}`. */
export async function getVerbConjugations(verb: string): Promise<Record<string, string>> {
  const [meta, verbs] = await Promise.all([getMeta(), getVerbs()]);
  const rank = verbs.find((x) => x.v === verb)?.rank;
  if (!rank) throw new Error(`Unknown verb: ${verb}`);
  const band = meta.bands.find((b) => rank >= b.lo && rank <= b.hi)!;
  const entry = (await load<Shard>(`/data/conjugations/${band.file}`))[verb];
  const out: Record<string, string> = {};
  for (const tense of meta.tenses) {
    const forms = entry[`${tense}.indicative`];
    meta.pronouns.forEach((p, i) => { if (forms?.[i]) out[`${tense}_${p}`] = forms[i]!; });
  }
  return out;
}
